package com.foundgine.samples.supplychain.advanced.semantic;

import com.foundgine.core.abstractions.*;
import com.foundgine.core.semantic.*;
import com.foundgine.samples.supplychain.advanced.domain.Domain;

/** Manual semantic contract for the advanced sample until Java AOT discovery is ported. */
public final class SupplyChainSemanticModel {
    public static final EntityId PRODUCT=EntityId.create("Product");
    public static final EntityId COMPONENT=EntityId.create("ProductComponent");
    public static final EntityId SUPPLIER=EntityId.create("Supplier");
    public static final EntityId SHIPMENT=EntityId.create("Shipment");
    public static final EntityId INVENTORY=EntityId.create("InventoryLot");
    public static final EntityId WAREHOUSE=EntityId.create("Warehouse");
    public static final EntityId BUSINESS_UNIT=EntityId.create("BusinessUnit");
    public static final EntityId CUSTOMER_ORDER=EntityId.create("CustomerOrder");
    public static final EntityId CUSTOMER_ORDER_LINE=EntityId.create("CustomerOrderLine");
    public static final EntityId PURCHASE_ORDER=EntityId.create("PurchaseOrder");
    public static final EntityId PURCHASE_ORDER_LINE=EntityId.create("PurchaseOrderLine");
    public static final EntityId CERTIFICATION=EntityId.create("SupplierCertification");
    public static final EntityId INCIDENT=EntityId.create("ComplianceIncident");

    public static SemanticModel build() {
        var b=new SemanticModelBuilder();
        b.entity(EntityId.create("Company"),"Company",e->e.identity("Id").field(FieldId.create("Company","Id"),"Id",Domain.CompanyId.class).field(FieldId.create("Company","Name"),"Name",String.class).field(FieldId.create("Company","TenantId"),"TenantId",String.class));
        b.entity(BUSINESS_UNIT,"BusinessUnit",e->e.identity("Id").field(FieldId.create("BusinessUnit","Id"),"Id",Domain.BusinessUnitId.class).field(FieldId.create("BusinessUnit","CompanyId"),"CompanyId",Domain.CompanyId.class).field(FieldId.create("BusinessUnit","Name"),"Name",String.class));
        b.entity(WAREHOUSE,"Warehouse",e->e.identity("Id").field(FieldId.create("Warehouse","Id"),"Id",Domain.WarehouseId.class).field(FieldId.create("Warehouse","BusinessUnitId"),"BusinessUnitId",Domain.BusinessUnitId.class).field(FieldId.create("Warehouse","Name"),"Name",String.class).field(FieldId.create("Warehouse","TenantId"),"TenantId",String.class).relationship(RelationshipId.create("Warehouse","businessUnit"),"businessUnit",BUSINESS_UNIT,RelationshipCardinality.ONE).relationship(RelationshipId.create("Warehouse","inventory"),"inventory",INVENTORY,RelationshipCardinality.MANY));
        b.entity(SUPPLIER,"Supplier",e->e.identity("Id").alias("Vendor",95).alias("Seller",90).field(FieldId.create("Supplier","Id"),"Id",Domain.SupplierId.class).field(FieldId.create("Supplier","Name"),"Name",String.class).field(FieldId.create("Supplier","Country"),"Country",String.class).fieldAlias(FieldId.create("Supplier","Country"),"State",85).field(FieldId.create("Supplier","RiskScore"),"RiskScore",java.math.BigDecimal.class).field(FieldId.create("Supplier","TenantId"),"TenantId",String.class).relationship(RelationshipId.create("Supplier","certifications"),"certifications",CERTIFICATION,RelationshipCardinality.MANY).relationship(RelationshipId.create("Supplier","incidents"),"incidents",INCIDENT,RelationshipCardinality.MANY).relationship(RelationshipId.create("Supplier","purchaseOrders"),"purchaseOrders",PURCHASE_ORDER,RelationshipCardinality.MANY));
        b.entity(COMPONENT,"ProductComponent",e->e.identity("ParentProductId").field(FieldId.create("ProductComponent","ParentProductId"),"ParentProductId",Domain.ProductId.class).field(FieldId.create("ProductComponent","ComponentProductId"),"ComponentProductId",Domain.ProductId.class).field(FieldId.create("ProductComponent","QuantityPerParent"),"QuantityPerParent",java.math.BigDecimal.class).field(FieldId.create("ProductComponent","EffectiveFrom"),"EffectiveFrom",java.time.LocalDate.class).field(FieldId.create("ProductComponent","EffectiveTo"),"EffectiveTo",java.time.LocalDate.class).field(FieldId.create("ProductComponent","Revision"),"Revision",String.class));
        b.entity(PRODUCT,"Product",e->e.identity("Id").field(FieldId.create("Product","Id"),"Id",Domain.ProductId.class).field(FieldId.create("Product","Sku"),"Sku",String.class).field(FieldId.create("Product","Name"),"Name",String.class).field(FieldId.create("Product","Category"),"Category",String.class).field(FieldId.create("Product","SafetyStock"),"SafetyStock",java.math.BigDecimal.class).relationship(RelationshipId.create("Product","components"),"components",COMPONENT,RelationshipCardinality.MANY).relationship(RelationshipId.create("Product","purchaseOrderLines"),"purchaseOrderLines",PURCHASE_ORDER_LINE,RelationshipCardinality.MANY).relationship(RelationshipId.create("Product","usedInComponents"),"usedInComponents",COMPONENT,RelationshipCardinality.MANY));
        b.entity(PURCHASE_ORDER,"PurchaseOrder",e->e.identity("Id").alias("PO",100).alias("POs",95).alias("Buy",90).alias("Buys",85).field(FieldId.create("PurchaseOrder","Id"),"Id",Domain.PurchaseOrderId.class).field(FieldId.create("PurchaseOrder","SupplierId"),"SupplierId",Domain.SupplierId.class).field(FieldId.create("PurchaseOrder","WarehouseId"),"WarehouseId",Domain.WarehouseId.class).field(FieldId.create("PurchaseOrder","Status"),"Status",Domain.PurchaseOrderStatus.class).field(FieldId.create("PurchaseOrder","OrderedOn"),"OrderedOn",java.time.LocalDate.class).field(FieldId.create("PurchaseOrder","ExpectedArrival"),"ExpectedArrival",java.time.LocalDate.class).fieldAlias(FieldId.create("PurchaseOrder","ExpectedArrival"),"DueDate",90).relationship(RelationshipId.create("PurchaseOrder","lines"),"lines",PURCHASE_ORDER_LINE,RelationshipCardinality.MANY).relationship(RelationshipId.create("PurchaseOrder","shipments"),"shipments",SHIPMENT,RelationshipCardinality.MANY).relationship(RelationshipId.create("PurchaseOrder","supplier"),"supplier",SUPPLIER,RelationshipCardinality.ONE));
        b.entity(PURCHASE_ORDER_LINE,"PurchaseOrderLine",e->e.identity("Id").field(FieldId.create("PurchaseOrderLine","Id"),"Id",Domain.PurchaseOrderLineId.class).field(FieldId.create("PurchaseOrderLine","PurchaseOrderId"),"PurchaseOrderId",Domain.PurchaseOrderId.class).field(FieldId.create("PurchaseOrderLine","ProductId"),"ProductId",Domain.ProductId.class).field(FieldId.create("PurchaseOrderLine","Quantity"),"Quantity",java.math.BigDecimal.class).field(FieldId.create("PurchaseOrderLine","UnitPrice"),"UnitPrice",java.math.BigDecimal.class).relationship(RelationshipId.create("PurchaseOrderLine","purchaseOrder"),"purchaseOrder",PURCHASE_ORDER,RelationshipCardinality.ONE));
        b.entity(SHIPMENT,"Shipment",e->e.identity("Id").field(FieldId.create("Shipment","Id"),"Id",Domain.ShipmentId.class).field(FieldId.create("Shipment","PurchaseOrderId"),"PurchaseOrderId",Domain.PurchaseOrderId.class).field(FieldId.create("Shipment","ExpectedArrival"),"ExpectedArrival",java.time.LocalDate.class).field(FieldId.create("Shipment","ActualArrival"),"ActualArrival",java.time.LocalDate.class).field(FieldId.create("Shipment","Status"),"Status",Domain.ShipmentStatus.class).field(FieldId.create("Shipment","Quantity"),"Quantity",java.math.BigDecimal.class));
        b.entity(INVENTORY,"InventoryLot",e->e.identity("Id").field(FieldId.create("InventoryLot","Id"),"Id",Domain.InventoryLotId.class).field(FieldId.create("InventoryLot","WarehouseId"),"WarehouseId",Domain.WarehouseId.class).field(FieldId.create("InventoryLot","ProductId"),"ProductId",Domain.ProductId.class).field(FieldId.create("InventoryLot","OnHand"),"OnHand",java.math.BigDecimal.class).field(FieldId.create("InventoryLot","Reserved"),"Reserved",java.math.BigDecimal.class).field(FieldId.create("InventoryLot","Quarantined"),"Quarantined",java.math.BigDecimal.class).relationship(RelationshipId.create("InventoryLot","warehouse"),"warehouse",WAREHOUSE,RelationshipCardinality.ONE));
        b.entity(CUSTOMER_ORDER,"CustomerOrder",e->e.identity("Id").field(FieldId.create("CustomerOrder","Id"),"Id",Domain.CustomerOrderId.class).field(FieldId.create("CustomerOrder","BusinessUnitId"),"BusinessUnitId",Domain.BusinessUnitId.class).field(FieldId.create("CustomerOrder","PlacedOn"),"PlacedOn",java.time.LocalDate.class).field(FieldId.create("CustomerOrder","Status"),"Status",String.class));
        b.entity(CUSTOMER_ORDER_LINE,"CustomerOrderLine",e->e.identity("Id").field(FieldId.create("CustomerOrderLine","Id"),"Id",Domain.CustomerOrderLineId.class).field(FieldId.create("CustomerOrderLine","CustomerOrderId"),"CustomerOrderId",Domain.CustomerOrderId.class).field(FieldId.create("CustomerOrderLine","ProductId"),"ProductId",Domain.ProductId.class).field(FieldId.create("CustomerOrderLine","Quantity"),"Quantity",java.math.BigDecimal.class));
        b.entity(CERTIFICATION,"SupplierCertification",e->e.identity("Id").field(FieldId.create("SupplierCertification","Id"),"Id",Domain.CertificationId.class).field(FieldId.create("SupplierCertification","SupplierId"),"SupplierId",Domain.SupplierId.class).field(FieldId.create("SupplierCertification","Type"),"Type",String.class).field(FieldId.create("SupplierCertification","ValidFrom"),"ValidFrom",java.time.LocalDate.class).field(FieldId.create("SupplierCertification","ValidTo"),"ValidTo",java.time.LocalDate.class));
        b.entity(INCIDENT,"ComplianceIncident",e->e.identity("Id").field(FieldId.create("ComplianceIncident","Id"),"Id",Integer.class).field(FieldId.create("ComplianceIncident","SupplierId"),"SupplierId",Domain.SupplierId.class).field(FieldId.create("ComplianceIncident","Severity"),"Severity",String.class).field(FieldId.create("ComplianceIncident","OccurredOn"),"OccurredOn",java.time.LocalDate.class).field(FieldId.create("ComplianceIncident","Description"),"Description",String.class));
        b.traversal("Product","shipments","purchaseOrderLines","purchaseOrder","shipments");
        b.traversal("Product","supplierIncidents","purchaseOrderLines","purchaseOrder","supplier","incidents");
        return b.build();
    }
    private SupplyChainSemanticModel() {}
}
